// Bai tap ngu phap hsk4v3 — soan rieng theo trinh do (sinh tu data-grammar/hsk4v3/).
window.GRAMMAR_EXTRA = Object.assign(window.GRAMMAR_EXTRA || {}, {"/lessons/hsk4v3-bai-1.html":[{"point":"指示代词“任何” — bất kỳ, bất cứ","items":[{"context":"“Sau này có bất kỳ vấn đề gì đều có thể đến tìm cô.”","pre":"你们以后有","blank":"任何","post":"问题都可以来找我。","options":["任何","每","所有的"],"answer":0,"explanation":"任何 + danh từ + 都 + V."},{"context":"“Bất kỳ ai cũng không được đến muộn.”","pre":"明天8点出发，任何人","blank":"也","post":"不能迟到。","options":["也","就","才"],"answer":0,"explanation":"任何……也 + phủ định."},{"context":"“Có bất kỳ thông báo nào, tôi đều báo cho bạn ngay.”","pre":"学校有任何通知，我","blank":"都","post":"会第一时间告诉你。","options":["都","还","再"],"answer":0,"explanation":"任何……都…… — 都 đứng trước động từ của vế sau."},{"context":"“Việc này anh ấy không nói với bất kỳ ai.”","pre":"这件事他没有告诉","blank":"任何","post":"人。","options":["任何","什么的","哪"],"answer":0,"explanation":"没有 + V + 任何 + N."},{"context":"“Bất cứ lúc nào em cũng có thể gọi cho cô.”","pre":"","blank":"任何","post":"时候你都可以给我打电话。","options":["任何","那","一"],"answer":0,"explanation":"任何时候 = bất cứ lúc nào."},{"type":"sort","context":"Sắp xếp: “Em có bất kỳ vấn đề gì đều có thể hỏi tôi.”","words":["你","有","任何","问题","都","可以","问我"],"answer":"你有任何问题都可以问我。","explanation":"任何 + N + 都 + 可以 + V."},{"type":"sort","context":"Sắp xếp: “Bất kỳ ai cũng không được đến muộn.”","words":["任何人","也","不能","迟到"],"answer":"任何人也不能迟到。","explanation":"任何人 + 也 + 不能."},{"type":"sort","context":"Sắp xếp: “Việc này anh ấy không nói với ai cả.”","words":["他","没有","告诉","任何人","这件事"],"answer":"这件事他没有告诉任何人。","explanation":"Phủ định: 没有 + V + 任何 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"任何的学生都可以参加。","isCorrect":false,"correctVersion":"任何学生都可以参加。","explanation":"任何 + N, không thêm 的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们有任何问题都可以找王老师。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 任何问题 + 都 + 可以."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他不认识任何人们。","isCorrect":false,"correctVersion":"他不认识任何人。","explanation":"任何 không đi với 们."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bất cứ lúc nào em cũng có thể gọi điện cho cô.","answer":"任何时候你都可以给我打电话。","answerPy":"Rènhé shíhou nǐ dōu kěyǐ gěi wǒ dǎdiànhuà.","explanation":"任何时候 + 都 + 可以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trong thư viện, bất kỳ ai cũng không được nói to.","answer":"在图书馆里，任何人都不能大声说话。","answerPy":"Zài túshūguǎn lǐ, rènhé rén dōu bù néng dà shēng shuōhuà.","explanation":"任何人 + 都 / 也 + 不能."}]},{"point":"假设复句“要是……，就……” — nếu … thì …","items":[{"context":"“Nếu xin được học bổng thì …”","pre":"","blank":"要是","post":"申请到奖学金，就能减轻不少经济压力。","options":["要是","虽然","因为"],"answer":0,"explanation":"要是 nêu giả thiết."},{"context":"“… thì đi leo núi với tớ nhé.”","pre":"你要是明天有时间，","blank":"就","post":"跟我一起去爬山吧。","options":["就","才","也"],"answer":0,"explanation":"要是……，就……"},{"context":"“… thì chúng ta hỏi người khác.”","pre":"要是她不愿意参加比赛，我们","blank":"就","post":"再问问别人。","options":["就","还","都"],"answer":0,"explanation":"就 đứng sau chủ ngữ 我们."},{"context":"“Nếu bạn đói thì mình đi nhà ăn trước.” (ôn từ mới)","pre":"要是你饿了，我们就先去","blank":"食堂","post":"吧。","options":["食堂","签证","证件"],"answer":0,"explanation":"食堂 = nhà ăn."},{"context":"“Nếu không làm visa thì không thể sang Trung Quốc du học.”","pre":"","blank":"要是","post":"不办签证，就不能来中国留学。","options":["要是","一方面","随着"],"answer":0,"explanation":"要是 + phủ định 不……，就不能……"},{"type":"sort","context":"Sắp xếp: “Nếu mai mưa thì chúng ta không đi nữa.”","words":["要是","明天","下雨","，","我们","就","不去了"],"answer":"要是明天下雨，我们就不去了。","explanation":"要是 + giả thiết，chủ ngữ + 就 + V."},{"type":"sort","context":"Sắp xếp: “Nếu bạn mệt rồi thì nghỉ một chút đi.”","words":["你","要是","累了","，","就","休息","一下吧"],"answer":"你要是累了，就休息一下吧。","explanation":"要是 đứng sau chủ ngữ 你."},{"type":"sort","context":"Sắp xếp: “Nếu có vấn đề thì đến tìm tôi.”","words":["要是","有","问题","，","就","来","找我"],"answer":"要是有问题，就来找我。","explanation":"要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是你不舒服，就去看医生吧。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是明天有时间，我们去就看电影。","isCorrect":false,"correctVersion":"要是明天有时间，我们就去看电影。","explanation":"就 đứng trước động từ 去."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是我有钱，我就买一辆新车。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ 我 + 就 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu xin được học bổng thì tôi sẽ học thạc sĩ ở Trung Quốc.","answer":"要是申请到奖学金，我就在中国读硕士。","answerPy":"Yàoshi shēnqǐng dào jiǎngxuéjīn, wǒ jiù zài Zhōngguó dú shuòshì.","explanation":"要是……，就…… + từ mới 申请, 奖学金, 硕士."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn không hiểu thì hỏi cô giáo đi.","answer":"要是你不懂，就问老师吧。","answerPy":"Yàoshi nǐ bù dǒng, jiù wèn lǎoshī ba.","explanation":"要是……，就……吧."}]},{"point":"介词“随着” — cùng với, theo (sự thay đổi)","items":[{"context":"“Cùng với sự phát triển của Trung Quốc …”","pre":"","blank":"随着","post":"中国的发展，越来越多的外国学生来中国学习。","options":["随着","通过","除了"],"answer":0,"explanation":"随着 + N 的发展."},{"context":"“Cùng với trình độ tiếng Trung nâng cao …”","pre":"随着中文水平的","blank":"提高","post":"，我现在能看懂中文报纸了。","options":["提高","知识","方面"],"answer":0,"explanation":"随着……的提高."},{"context":"“Theo trời ngày càng nóng …”","pre":"随着天气","blank":"越来越","post":"热，人们都换上了凉快的衣服。","options":["越来越","一方面","任何"],"answer":0,"explanation":"随着 + 越来越 + tính từ."},{"context":"“Thông qua những giao lưu này …” (phân biệt với 随着)","pre":"","blank":"通过","post":"这些交流，外国学生能更快地适应中国的大学生活。","options":["通过","随着","要是"],"answer":0,"explanation":"通过 = nhờ/qua cách gì; 随着 = theo sự thay đổi."},{"context":"“… giao lưu cũng ngày càng nhiều.”","pre":"随着来中国留学的人越来越多，中国学生和外国学生的交流","blank":"也","post":"越来越多。","options":["也","就","才"],"answer":0,"explanation":"Vế sau thường có 也 + 越来越."},{"type":"sort","context":"Sắp xếp: “Cùng với kinh tế phát triển, đời sống mọi người ngày càng tốt.”","words":["随着","经济","的","发展","，","人们的生活","越来越好"],"answer":"随着经济的发展，人们的生活越来越好。","explanation":"随着 + N 的 + 发展，……越来越……"},{"type":"sort","context":"Sắp xếp: “Cùng với tuổi tác tăng lên, cậu ấy ngày càng hiểu chuyện.”","words":["随着","年龄","的","增长","，","他","越来越","懂事了"],"answer":"随着年龄的增长，他越来越懂事了。","explanation":"随着……的增长."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着我到了北京，就给你打电话。","isCorrect":false,"correctVersion":"我到了北京以后，就给你打电话。","explanation":"“Đến Bắc Kinh” là hành động, không phải sự thay đổi dần → dùng ……以后."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着生活水平的提高，人们越来越关注身体健康。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 随着……的提高，……越来越……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"人们都换上了凉快的衣服，随着天气越来越热。","isCorrect":false,"correctVersion":"随着天气越来越热，人们都换上了凉快的衣服。","explanation":"Cụm 随着 đặt ở đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cùng với sự phát triển kinh tế, ngày càng nhiều người đi du lịch nước ngoài.","answer":"随着经济的发展，越来越多的人去国外旅游。","answerPy":"Suízhe jīngjì de fāzhǎn, yuèláiyuè duō de rén qù guó wài lǚyóu.","explanation":"随着……的发展，越来越多的……"}]},{"point":"并列复句“一方面……，另一方面……” — một mặt …, mặt khác …","items":[{"context":"“… mặt khác vì tiện.”","pre":"他经常在网上买东西，一方面因为便宜，","blank":"另一方面","post":"因为方便。","options":["另一方面","一方面","另外"],"answer":0,"explanation":"一方面……，另一方面……"},{"context":"“… mặt khác cũng giảm được áp lực.”","pre":"多做运动一方面能让身体更健康，另一方面","blank":"也","post":"能减轻压力。","options":["也","就","才"],"answer":0,"explanation":"Vế 另一方面 thường có 也."},{"context":"“Một mặt là để học ngôn ngữ …”","pre":"来中国留学，","blank":"一方面","post":"是为了学习语言，另一方面也是为将来做准备。","options":["一方面","随着","要是"],"answer":0,"explanation":"Vế đầu dùng 一方面."},{"context":"“… kiến thức về thương mại quốc tế.” (ôn từ 方面)","pre":"我想了解更多国际贸易","blank":"方面","post":"的知识。","options":["方面","知识","专业"],"answer":0,"explanation":"N + 方面的知识."},{"type":"sort","context":"Sắp xếp: “Tôi đạp xe đi làm, một mặt tốt cho môi trường, mặt khác cũng tốt cho sức khỏe.”","words":["我","骑车上班","，","一方面","对环境好","，","另一方面","对身体也好"],"answer":"我骑车上班，一方面对环境好，另一方面对身体也好。","explanation":"一方面……，另一方面……也……"},{"type":"sort","context":"Sắp xếp: “Học tiếng Trung một mặt vì công việc, mặt khác để hiểu văn hóa Trung Quốc.”","words":["学中文","一方面","为了","工作","，","另一方面","为了","了解中国文化"],"answer":"学中文一方面为了工作，另一方面为了了解中国文化。","explanation":"Hai vế cân đối: 为了……，为了……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一方面是学生，另外方面是老师。","isCorrect":false,"correctVersion":"他一方面是学生，另一方面也是老师。","explanation":"Phải là 另一方面."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我住在学校里，一方面因为便宜，另一方面因为方便。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nêu hai lý do song song."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一方面天气很好，一方面我们去公园吧。","isCorrect":false,"correctVersion":"天气很好，我们去公园吧。","explanation":"Hai vế không phải hai mặt song song của một sự việc → không dùng cấu trúc này."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi chọn ngành kinh tế, một mặt vì có hứng thú, mặt khác vì sau này muốn làm thương mại quốc tế.","answer":"我选择经济专业，一方面是因为感兴趣，另一方面是因为将来想做国际贸易。","answerPy":"Wǒ xuǎnzé jīngjì zhuānyè, yìfāngmiàn shì yīnwèi gǎnxìngqù, lìngyìfāngmiàn shì yīnwèi jiānglái xiǎng zuò guójì màoyì.","explanation":"一方面……，另一方面…… + từ mới 专业, 将来, 国际贸易."}]}],"/lessons/hsk4v3-bai-2.html":[{"point":"固定格式“×就是了” — cứ … là được","items":[{"context":"“Nếu quyết định thuê thì cứ báo tôi là được.”","pre":"如果决定租了，告诉我","blank":"就是了","post":"。","options":["就是了","就是","是了"],"answer":0,"explanation":"Cấu trúc cố định: V + 就是了 (phải có 了)."},{"context":"“Tôi nhất định làm được, ông cứ yên tâm.”","pre":"我一定能办到，您","blank":"放心","post":"就是了。","options":["放心","担心","关心"],"answer":0,"explanation":"放心就是了 = cứ yên tâm."},{"context":"“Lần sau cố gắng là được.”","pre":"这次考得不好没关系，下次努力","blank":"就是了","post":"。","options":["就是了","才是了","也是了"],"answer":0,"explanation":"Đặt 就是了 ở cuối câu để động viên."},{"context":"“Bạn hài lòng thì cứ thuê luôn.” (ôn từ mới + 要是 – Bài 1)","pre":"你要是满意，","blank":"租","post":"下来就是了。","options":["租","出租","房租"],"answer":0,"explanation":"租下来 = thuê luôn; 出租 = cho thuê; 房租 = tiền thuê."},{"context":"“Phòng đã dọn xong, hôm nay bạn cứ dọn vào.”","pre":"房间已经","blank":"收拾","post":"好了，你今天搬进来就是了。","options":["收拾","入住","毕业"],"answer":0,"explanation":"收拾好了 = dọn dẹp xong."},{"type":"sort","context":"Sắp xếp: “Nếu bạn hài lòng thì cứ thuê luôn đi.”","words":["你","要是","满意","，","租下来","就是了"],"answer":"你要是满意，租下来就是了。","explanation":"要是……，V + 就是了."},{"type":"sort","context":"Sắp xếp: “Có bất kỳ vấn đề gì cứ gọi cho tôi là được.”","words":["有","任何","问题","，","给我","打电话","就是了"],"answer":"有任何问题，给我打电话就是了。","explanation":"Ôn 任何 (Bài 1) + 就是了 cuối câu."},{"type":"sort","context":"Sắp xếp: “Không biết làm cũng không sao, tôi dạy bạn là được.”","words":["不会","做","没关系","，","我","教你","就是了"],"answer":"不会做没关系，我教你就是了。","explanation":"Chủ ngữ 我 + V + 就是了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你别担心，我明天一定来就是了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 就是了 cuối câu, trấn an người nghe."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，你买下来就是。","isCorrect":false,"correctVersion":"这件衣服很漂亮，你买下来就是了。","explanation":"Thiếu 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"就是了你下次努力。","isCorrect":false,"correctVersion":"你下次努力就是了。","explanation":"就是了 phải đặt cuối câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn thích thì cứ lấy đi là được.","answer":"你要是喜欢，拿走就是了。","answerPy":"Nǐ yàoshi xǐhuan, ná zǒu jiùshì le.","explanation":"要是……，V + 就是了 (ôn Bài 1 · điểm 2)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Có bất kỳ vấn đề gì, bạn cứ hỏi tôi là được.","answer":"有任何问题，你问我就是了。","answerPy":"Yǒu rènhé wèntí, nǐ wèn wǒ jiùshì le.","explanation":"任何 (Bài 1 · điểm 1) + 就是了."}]},{"point":"转折复句“……，不过……” — …, có điều …","items":[{"context":"“Môi trường đẹp thật, có điều nghe nói gần đây có nhiều công ty.”","pre":"这个小区的环境真不错，","blank":"不过","post":"我听说，附近有十几家公司。","options":["不过","所以","而且"],"answer":0,"explanation":"Vế sau chuyển ý → 不过."},{"context":"“… có điều không thấy gấu trúc.”","pre":"我们在动物园看见了很多动物，不过","blank":"没","post":"看见大熊猫。","options":["没","不","别"],"answer":0,"explanation":"Phủ định việc đã xảy ra: 没 + V."},{"context":"“… có điều rất nhanh đã thích nghi.” (ôn từ Bài 1)","pre":"我刚来北京时还不太习惯这里的天气，不过很快就","blank":"适应","post":"了。","options":["适应","交流","申请"],"answer":0,"explanation":"适应 = thích nghi."},{"context":"“Phòng này khá sáng, có điều hơi nhỏ.”","pre":"这个房间挺","blank":"亮","post":"，不过有点儿小。","options":["亮","租","种"],"answer":0,"explanation":"挺亮 = khá sáng (tính từ)."},{"context":"“Tiền thuê không cao, có điều hơi xa công ty.”","pre":"房租不高，","blank":"不过","post":"离公司有点儿远。","options":["不过","因为","并且"],"answer":0,"explanation":"Khen trước, góp ý sau → 不过."},{"type":"sort","context":"Sắp xếp: “Chiếc điện thoại này cũng được, có điều hơi đắt.”","words":["这个手机","还可以","，","不过","有点儿贵"],"answer":"这个手机还可以，不过有点儿贵。","explanation":"……，不过 + ý chuyển."},{"type":"sort","context":"Sắp xếp: “Nhà rất đẹp, có điều xung quanh không yên tĩnh lắm.”","words":["房子","很漂亮","，","不过","周围","不太安静"],"answer":"房子很漂亮，不过周围不太安静。","explanation":"不过 đứng trước chủ ngữ vế sau (周围)."},{"type":"sort","context":"Sắp xếp: “Tôi rất muốn đi, có điều e là không có thời gian.”","words":["我","很想去","，","不过","恐怕","没有时间"],"answer":"我很想去，不过恐怕没有时间。","explanation":"不过 + 恐怕 (từ mới bài này)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个小区很安静，不过环境也很好。","isCorrect":false,"correctVersion":"这个小区很安静，而且环境也很好。","explanation":"Hai ý cùng chiều tốt → dùng 而且, không dùng 不过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气预报说明天是晴天，不过可能会刮风。","isCorrect":true,"correctVersion":"","explanation":"Đúng: trời nắng (tốt) — có điều có gió (chưa tốt)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不过他很忙，他每天都去跑步。","isCorrect":false,"correctVersion":"他很忙，不过每天都去跑步。","explanation":"不过 đứng ở đầu vế SAU."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Căn nhà này vị trí rất tốt, có điều tiền thuê hơi đắt.","answer":"这个房子位置很好，不过房租有点儿贵。","answerPy":"Zhège fángzi wèizhì hěn hǎo, búguò fángzū yǒudiǎnr guì.","explanation":"位置, 房租 (từ mới) + 不过."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi rất muốn đi du lịch, có điều e là không có thời gian.","answer":"我很想去旅游，不过恐怕没有时间。","answerPy":"Wǒ hěn xiǎng qù lǚyóu, búguò kǒngpà méiyǒu shíjiān.","explanation":"不过 + 恐怕."}]},{"point":"连词/副词“并” — và, đồng thời; hoàn toàn (không)","items":[{"context":"“… và chỉ cho tôi cách dùng.”","pre":"房东又向我介绍了一下房子里的东西，","blank":"并","post":"告诉我这些东西怎么用。","options":["并","和","跟"],"answer":0,"explanation":"Nối hai cụm động từ → 并 (和 nối danh từ)."},{"context":"“… lần thuê nhà này chẳng hề dễ.”","pre":"对白家月来说，这次租房并","blank":"不","post":"容易。","options":["不","没","很"],"answer":0,"explanation":"并不 + tính từ."},{"context":"“… và xin được học bổng.” (ôn từ Bài 1)","pre":"她考上了北京大学并申请到了","blank":"奖学金","post":"。","options":["奖学金","房租","工资"],"answer":0,"explanation":"申请到 + 奖学金."},{"context":"“Tôi đâu có đồng ý thuê ngay …”","pre":"我","blank":"并","post":"没有答应你就租这个房子，我还要再想想。","options":["并","也","就"],"answer":0,"explanation":"并没有 = phủ định mạnh, phản bác."},{"context":"“Học chữ Hán chẳng khó, cứ viết nhiều luyện nhiều là được.” (ôn 就是了 – điểm 1)","pre":"学汉字","blank":"并","post":"不难，多写多练就是了。","options":["并","和","还"],"answer":0,"explanation":"并不难 = chẳng khó chút nào."},{"type":"sort","context":"Sắp xếp: “Tốt nghiệp xong anh ấy đến Bắc Kinh làm việc, và thuê một căn nhà gần công ty.”","words":["他","毕业后","来北京工作","，","并","在公司附近","租了个房子"],"answer":"他毕业后来北京工作，并在公司附近租了个房子。","explanation":"V1……，并 + V2……"},{"type":"sort","context":"Sắp xếp: “Khu chung cư này chẳng yên tĩnh chút nào.”","words":["这个","小区","并","不","安静"],"answer":"这个小区并不安静。","explanation":"并不 + Adj."},{"type":"sort","context":"Sắp xếp: “Chúng tôi đã thảo luận vấn đề này và đưa ra quyết định.”","words":["我们","讨论了","这个问题","，","并","做出了","决定"],"answer":"我们讨论了这个问题，并做出了决定。","explanation":"Hai hành động nối tiếp, cùng chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了苹果并香蕉。","isCorrect":false,"correctVersion":"我买了苹果和香蕉。","explanation":"并 không nối hai danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"其实这个问题并不难。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 并不 phản bác suy nghĩ “khó”."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在北京租房子不并容易。","isCorrect":false,"correctVersion":"在北京租房子并不容易。","explanation":"Thứ tự đúng: 并不."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cô ấy tìm được việc làm và thuê một căn nhà gần công ty.","answer":"她找到了工作，并在公司附近租了一个房子。","answerPy":"Tā zhǎo dào le gōngzuò, bìng zài gōngsī fùjìn zū le yí gè fángzi.","explanation":"并 nối hai hành động, không lặp chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thực ra thuê nhà ở Bắc Kinh chẳng hề rẻ.","answer":"其实在北京租房子并不便宜。","answerPy":"Qí shízai Běijīng zū fángzi bìng bú piányi.","explanation":"并不 + Adj: phản bác suy nghĩ “rẻ”."}]},{"point":"连词/介词“由于” — do, bởi vì","items":[{"context":"“Do trời mưa to suốt, nên …”","pre":"","blank":"由于","post":"一直下大雨，所以我们决定不爬山了。","options":["由于","虽然","要是"],"answer":0,"explanation":"由于……，所以…… (nhân quả)."},{"context":"“… nên lúc đầu họ cũng không mua nhà.”","pre":"由于很多刚工作的年轻人工资还不太高，","blank":"所以","post":"他们一开始也不买房。","options":["所以","但是","而且"],"answer":0,"explanation":"Vế sau của 由于 dùng 所以 / 因此."},{"context":"“Nhờ sự nỗ lực của mọi người …”","pre":"由于大家的","blank":"努力","post":"，这次运动会我们班获得了第一名。","options":["努力","房租","位置"],"answer":0,"explanation":"Giới từ: 由于 + danh từ."},{"context":"“… vì vậy nhiều người thích thuê nhà ở đây.”","pre":"由于这个小区很安静，房子价格也不高，","blank":"因此","post":"，很多人都喜欢在这里租房子。","options":["因此","不过","并"],"answer":0,"explanation":"由于……，因此…… (因此 yīncǐ = vì vậy)."},{"context":"“… cô ấy quyết định thuê nhà gần công ty.”","pre":"由于新公司离她住的地方比较远，她决定在公司","blank":"附近","post":"租个房子。","options":["附近","价格","信息"],"answer":0,"explanation":"在 + nơi + 附近 = ở gần …"},{"type":"sort","context":"Sắp xếp: “Do điện thoại hết pin, cô ấy không có cách nào gọi điện.”","words":["由于","手机","没电了","，","她","没有办法","打电话"],"answer":"由于手机没电了，她没有办法打电话。","explanation":"由于 + nguyên nhân，kết quả."},{"type":"sort","context":"Sắp xếp: “Do lương không cao lắm nên anh ấy chọn thuê nhà.”","words":["由于","工资","不太高","，","所以","他","选择租房"],"answer":"由于工资不太高，所以他选择租房。","explanation":"由于……，所以……"},{"type":"sort","context":"Sắp xếp: “Nhờ sự giúp đỡ của mọi người, chúng tôi đã nhanh chóng hoàn thành công việc.”","words":["由于","大家的","帮助","，","我们","很快就","完成了工作"],"answer":"由于大家的帮助，我们很快就完成了工作。","explanation":"Giới từ: 由于 + cụm danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于天气不好，所以飞机晚到了两个小时。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 由于……，所以……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于下雨，但是比赛没有停。","isCorrect":false,"correctVersion":"虽然下雨，但是比赛没有停。","explanation":"Đây là quan hệ nhượng bộ → 虽然……但是……; 由于 chỉ nguyên nhân."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我没去上课，由于我生病了。","isCorrect":false,"correctVersion":"由于我生病了，所以没去上课。","explanation":"由于 đứng ở vế trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Do lương còn chưa cao nên nhiều người trẻ chọn thuê nhà.","answer":"由于工资还不太高，所以很多年轻人选择租房。","answerPy":"Yóuyú gōngzī hái bú tài gāo, suǒyǐ hěn duō niánqīngrén xuǎnzé zū fáng.","explanation":"由于……，所以…… + từ mới 工资."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp.","answer":"由于李文的帮助，白家月租到了合适的房子。","answerPy":"Yóuyú Lǐ Wén de bāngzhù, Bái Jiāyuè zū dào le héshì de fángzi.","explanation":"Giới từ: 由于 + cụm danh từ."}]}],"/lessons/hsk4v3-bai-3.html":[{"point":"转折复句“……×是×，就是/不过……” — … thì … thật, nhưng / chỉ là …","items":[{"context":"“Bắc Kinh to thì to thật, nhưng …”","pre":"北京大是","blank":"大","post":"，不过这边的路基本上都是正南正北的。","options":["大","很大","太大"],"answer":0,"explanation":"Hai bên 是 lặp lại đúng một từ: 大是大."},{"context":"“Căn nhà này rẻ thì rẻ thật, chỉ là cách công ty xa quá.”","pre":"这个房子便宜是便宜，","blank":"就是","post":"离我的公司太远了。","options":["就是","所以","因为"],"answer":0,"explanation":"Vế sau dùng 就是 / 不过 chỉ ra hạn chế."},{"context":"“Chúng tôi nghĩ thì có nghĩ rồi …”","pre":"我们想是","blank":"想","post":"了，就是没想出更好的办法。","options":["想","想想","想到"],"answer":0,"explanation":"想是想了 — 了 ở cuối khung."},{"context":"“… chỉ là dễ tiêu tiền lung tung.” (ôn từ mới)","pre":"网购方便是方便，就是容易","blank":"乱","post":"花钱。","options":["乱","正","直接"],"answer":0,"explanation":"乱花钱 = tiêu tiền lung tung."},{"context":"“Mát thì mát rồi, có điều mùa hè chưa hết …”","pre":"凉快是凉快了，","blank":"不过","post":"夏天还没结束，过几天又会热起来了。","options":["不过","于是","甚至"],"answer":0,"explanation":"×是×，不过……"},{"type":"sort","context":"Sắp xếp: “Cái áo này đẹp thì đẹp thật, chỉ là hơi đắt.”","words":["这件衣服","好看","是","好看","，","就是","有点儿贵"],"answer":"这件衣服好看是好看，就是有点儿贵。","explanation":"A是A，就是……"},{"type":"sort","context":"Sắp xếp: “Phần mềm này tiện thì tiện thật, nhưng tôi vẫn chưa biết dùng lắm.”","words":["这个软件","方便","是","方便","，","不过","我还不太会用"],"answer":"这个软件方便是方便，不过我还不太会用。","explanation":"A是A，不过……"},{"type":"sort","context":"Sắp xếp: “Bài tập viết xong thì viết xong rồi, nhưng có câu không biết làm.”","words":["作业","写完","是","写完了","，","不过","有的题","不会写"],"answer":"作业写完是写完了，不过有的题不会写。","explanation":"Cụm động từ: 写完是写完了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"北京大是很大，不过路很好找。","isCorrect":false,"correctVersion":"北京大是大，不过路很好找。","explanation":"Hai bên 是 giống hệt nhau, không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜好吃是好吃，就是价格有点儿高。","isCorrect":true,"correctVersion":"","explanation":"Đúng: A是A，就是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我累是累，所以还想再学一会儿。","isCorrect":false,"correctVersion":"我累是累，不过还想再学一会儿。","explanation":"Vế sau là chuyển ngoặt → 不过 / 就是, không dùng 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại này đẹp thì đẹp thật, chỉ là hơi đắt.","answer":"这个手机好看是好看，就是有点儿贵。","answerPy":"Zhège shǒujī hǎokàn shì hǎokàn, jiù shì yǒudiǎnr guì.","explanation":"A是A，就是 / 不过……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi muốn đi thì muốn thật, có điều hôm nay không có thời gian.","answer":"我想去是想去，不过今天没有时间。","answerPy":"Wǒ xiǎng qù shì xiǎng qù, búguò jīntiān méiyǒu shíjiān.","explanation":"Cụm động từ 想去是想去."}]},{"point":"递进复句“不仅/不光……，还/而且……” — không những … mà còn …","items":[{"context":"“Giờ tôi không những biết quét mã thanh toán …”","pre":"现在我","blank":"不仅","post":"会扫码结账，还会用手机在网上购物了。","options":["不仅","虽然","要是"],"answer":0,"explanation":"不仅……，还……"},{"context":"“… mà còn đưa chúng tôi tìm hiểu văn hóa.”","pre":"王老师不光教我们说中文，","blank":"而且","post":"带我们了解中国文化。","options":["而且","但是","所以"],"answer":0,"explanation":"不光……，而且……"},{"context":"“… mà còn bán cà phê và trà sữa.”","pre":"现在很多书店不仅卖书，","blank":"还","post":"卖咖啡和奶茶。","options":["还","就","才"],"answer":0,"explanation":"还 đứng ngay trước động từ 卖."},{"context":"“… mà còn gửi được chuyển phát nhanh.” (ôn từ mới)","pre":"这个软件不仅能支付，还能","blank":"寄","post":"快递。","options":["寄","管","转"],"answer":0,"explanation":"寄快递 = gửi chuyển phát nhanh."},{"context":"“… mà giao hàng còn nhanh.”","pre":"在中国网购，不仅选择多、价格不高，","blank":"而且","post":"送货很快。","options":["而且","于是","不过"],"answer":0,"explanation":"不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Cô ấy không những biết hát bài tiếng Trung, mà còn hát rất hay.”","words":["她","不仅","会唱","中文歌","，","而且","唱得很好"],"answer":"她不仅会唱中文歌，而且唱得很好。","explanation":"Chủ ngữ + 不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Tôi không những biết quét mã thanh toán, mà còn biết mua online.”","words":["我","不仅","会","扫码结账","，","还","会","网购"],"answer":"我不仅会扫码结账，还会网购。","explanation":"还 + 会 + V."},{"type":"sort","context":"Sắp xếp: “Quán này không những món ngon mà giá cũng không cao.”","words":["这家饭馆","不光","菜好吃","，","而且","价格","也不高"],"answer":"这家饭馆不光菜好吃，而且价格也不高。","explanation":"而且……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不仅他会说中文，还会说英文。","isCorrect":false,"correctVersion":"他不仅会说中文，还会说英文。","explanation":"Cùng chủ ngữ → chủ ngữ đứng trước 不仅."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在很多书店不仅卖书，还卖咖啡和奶茶。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ + 不仅……，还……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她不仅很漂亮，但是很聪明。","isCorrect":false,"correctVersion":"她不仅很漂亮，而且很聪明。","explanation":"不仅 đi với 而且 / 还, không đi với 但是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thanh toán bằng điện thoại không những nhanh mà còn rất tiện.","answer":"用手机支付不仅很快，而且很方便。","answerPy":"Yòng shǒujī zhīfù bùjǐn hěn kuài, érqiě hěn fāngbiàn.","explanation":"不仅……，而且 / 还……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cậu ấy không những giúp tôi tải WeChat, mà còn dạy tôi cách dùng.","answer":"他不仅帮我下载了微信，还教我怎么用。","answerPy":"Tā bùjǐn bāng wǒ xiàzài le Wēixìn, hái jiào wǒ zěnme yòng.","explanation":"Chủ ngữ 他 đứng trước 不仅."}]},{"point":"连词“甚至” — thậm chí, ngay cả","items":[{"context":"“… nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm.”","pre":"在中国网购，送货很快，很多留学生","blank":"甚至","post":"改变了自己的购物习惯。","options":["甚至","不仅","于是"],"answer":0,"explanation":"甚至 + V: nhấn mạnh điều vượt dự đoán."},{"context":"“Tàu cao tốc nhanh thật, thậm chí chưa nhìn rõ …”","pre":"高铁速度真快，","blank":"甚至","post":"还没看清楚，它就已经开过去了。","options":["甚至","虽然","要是"],"answer":0,"explanation":"甚至 đứng trước phần được nhấn mạnh."},{"context":"“… thậm chí còn có một siêu thị.”","pre":"这个小区真不错，有小花园、球场，甚至","blank":"还","post":"有一个超市。","options":["还","就","才"],"answer":0,"explanation":"甚至还 + 有……"},{"context":"“… thậm chí ngay cả thời gian ăn cơm cũng không có.”","pre":"他太忙了，甚至","blank":"连","post":"吃饭的时间都没有。","options":["连","把","被"],"answer":0,"explanation":"甚至连……都……"},{"context":"“… thậm chí nhiều người nổi tiếng cũng đến uống.”","pre":"这家咖啡店很有名，甚至很多","blank":"名人","post":"都会来喝咖啡。","options":["名人","手指","现金"],"answer":0,"explanation":"名人 = người nổi tiếng."},{"type":"sort","context":"Sắp xếp: “Anh ấy hiểu tôi quá, thậm chí tôi chưa nói anh ấy đã biết tôi muốn làm gì.”","words":["他","太了解我了","，","甚至","我还没说话","，","他就知道","我想做什么"],"answer":"他太了解我了，甚至我还没说话，他就知道我想做什么。","explanation":"甚至 + câu ngắn (还没……就……)."},{"type":"sort","context":"Sắp xếp: “Khu này có vườn hoa, sân bóng, thậm chí còn có một siêu thị.”","words":["这个小区","有小花园、球场","，","甚至","还有","一个超市"],"answer":"这个小区有小花园、球场，甚至还有一个超市。","explanation":"Liệt kê: 甚至 trước mục cuối."},{"type":"sort","context":"Sắp xếp: “Anh ấy bận đến mức thậm chí quên cả ăn cơm.”","words":["他","忙得","甚至","连饭","都","忘了吃"],"answer":"他忙得甚至连饭都忘了吃。","explanation":"V得 + 甚至连……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"甚至在中国寄快递很快。","isCorrect":false,"correctVersion":"在中国寄快递特别快，甚至上午寄出下午就收到了。","explanation":"甚至 không mở đầu câu; phần sau 甚至 phải vượt dự đoán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他中文说得很好，甚至能看懂中文报纸。","isCorrect":true,"correctVersion":"","explanation":"Đúng: đọc hiểu báo là mức cao hơn nói tốt."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天起得很早，甚至七点起床。","isCorrect":false,"correctVersion":"他每天起得很早，甚至五点就起床了。","explanation":"Phần sau 甚至 phải nổi bật hơn hẳn; 7 giờ không “sớm” đến mức bất ngờ, thêm 就……了 nhấn mạnh."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ở Trung Quốc mọi người đều dùng điện thoại trả tiền, thậm chí mua một chai nước cũng quét mã.","answer":"在中国大家都用手机支付，甚至买一瓶水也扫码。","answerPy":"Zài Zhōngguó dàjiā dōu yòng shǒujī zhīfù, shènzhì mǎi yì píng shuǐ yě sǎomǎ.","explanation":"甚至 + phần bất ngờ + 也 / 都."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy bận lắm, thậm chí cuối tuần cũng phải đi làm.","answer":"他很忙，甚至周末也要上班。","answerPy":"Tā hěn máng, shènzhì zhōumò yě yào shàngbān.","explanation":"甚至 + 周末也……"}]},{"point":"承接复句“……，于是……” — …, thế là …","items":[{"context":"“… thế là có người nói ra nỗi lo trên mạng.”","pre":"我们担心个人信息能否得到保护，","blank":"于是","post":"有人在网上说出了自己的担心。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 đứng đầu vế sau."},{"context":"“… thế là lên đại học chọn học y.”","pre":"她从小就想当医生，于是上大学时就选择了学","blank":"医","post":"。","options":["医","法律","技术"],"answer":0,"explanation":"学医 = học y; 当医生 ôn Bài 1."},{"context":"“… quyết định khỏi bệnh sẽ tập thể dục.”","pre":"最近总感冒，于是他决定病好后就开始","blank":"锻炼","post":"身体。","options":["锻炼","保护","改变"],"answer":0,"explanation":"锻炼身体 = rèn luyện thân thể (HSK 3)."},{"context":"“… thế là tôi cũng không muốn nói nữa.”","pre":"大家都不说话，于是我","blank":"也","post":"不想说话了。","options":["也","才","再"],"answer":0,"explanation":"于是 + chủ ngữ + 也……"},{"context":"“… thế là tôi đi thư viện một mình.” (综合练习 3)","pre":"在十字路口等了半个小时，他们也没来，","blank":"于是","post":"我就一个人去图书馆了。","options":["于是","而且","甚至"],"answer":0,"explanation":"于是……就……"},{"type":"sort","context":"Sắp xếp: “Tôi rất mệt, thế là về nhà nghỉ.”","words":["我","很累","，","于是","就","回家","休息了"],"answer":"我很累，于是就回家休息了。","explanation":"……，于是就……"},{"type":"sort","context":"Sắp xếp: “Anh ấy không thạo đường, thế là hỏi đường một bạn học.”","words":["他","不熟悉路","，","于是","向","一位同学","问路"],"answer":"他不熟悉路，于是向一位同学问路。","explanation":"于是 + 向 + ai + V."},{"type":"sort","context":"Sắp xếp: “Điện thoại hết pin, thế là tôi trả bằng tiền mặt.”","words":["手机没电了","，","于是","我","用现金","结了账"],"answer":"手机没电了，于是我用现金结了账。","explanation":"于是 + chủ ngữ 我 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"于是天黑了，我们回家了。","isCorrect":false,"correctVersion":"天黑了，于是我们回家了。","explanation":"于是 đứng đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他想学好中文，于是来中国留学了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: việc trước dẫn đến việc sau, đã xảy ra."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天冷了，于是你多穿点儿衣服吧。","isCorrect":false,"correctVersion":"天冷了，你多穿点儿衣服吧。","explanation":"Câu khuyên → không dùng 于是 (có thể dùng 所以)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi không biết dùng WeChat, thế là bạn Trung Quốc dạy tôi.","answer":"我不会用微信，于是中国朋友教我。","answerPy":"Wǒ bú huì yòng Wēixìn, yúshì Zhōngguó péngyou jiào wǒ.","explanation":"……，于是……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mua online quá tiện, thế là cô ấy hay tiêu tiền lung tung.","answer":"网购太方便了，于是她常常乱花钱。","answerPy":"Wǎnggòu tài fāngbiàn le, yúshì tā chángcháng luàn huā qián.","explanation":"于是 + chủ ngữ + V; từ mới 网购, 乱."}]}],"/lessons/hsk4v3-bai-4.html":[{"point":"可能补语“动词+得/不+了” — làm được / không làm được","items":[{"context":"“Điện thoại không có sóng, không lên mạng được.”","pre":"手机没有信号，上","blank":"不了","post":"网。","options":["不了","得了","不能"],"answer":0,"explanation":"上网 là từ ly hợp → 上不了网."},{"context":"“Hôm nay cô ấy không đến được nữa.”","pre":"她刚才给我发信息，说她今天来","blank":"不了","post":"了。","options":["不了","得了","没有"],"answer":0,"explanation":"来不了 = không đến được; 了 cuối câu báo sự thay đổi."},{"context":"“… có tham gia được không?”","pre":"明天的足球比赛，你们班男生参加","blank":"得了","post":"吗？","options":["得了","了得","得不"],"answer":0,"explanation":"Hỏi khả năng: V + 得了 + 吗？"},{"context":"“Món gọi không nhiều, ăn hết được.”","pre":"咱们点的菜不多，吃","blank":"得了","post":"。","options":["得了","不了","了"],"answer":0,"explanation":"菜不多 → 吃得了 (ăn hết được)."},{"context":"“Mất ví rồi, không mua được vé tàu điện ngầm.”","pre":"我的钱包丢了，买","blank":"不了","post":"地铁票了。","options":["不了","得了","不能"],"answer":0,"explanation":"买不了 + tân ngữ."},{"type":"sort","context":"Sắp xếp: “Điện thoại không có sóng, tôi không lên mạng được.”","words":["手机","没有信号","，","我","上不了","网"],"answer":"手机没有信号，我上不了网。","explanation":"上 + 不了 + 网."},{"type":"sort","context":"Sắp xếp: “Mai bạn có đến được không?”","words":["明天","你","来得了","来不了","？"],"answer":"明天你来得了来不了？","explanation":"Câu hỏi chính phản: V得了V不了？"},{"type":"sort","context":"Sắp xếp: “Nhiều món thế này, chúng mình ăn hết được không?”","words":["这么多","菜","，","咱们","吃得了","吗","？"],"answer":"这么多菜，咱们吃得了吗？","explanation":"V得了吗？"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我今天有点儿事，去不了你家了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 去不了 + nơi chốn + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨太大了，我们出门不了。","isCorrect":false,"correctVersion":"雨太大了，我们出不了门。","explanation":"出门 là từ ly hợp: 出不了门."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他病了，明天不能来不了。","isCorrect":false,"correctVersion":"他病了，明天来不了。","explanation":"Bỏ 不能 — không phủ định hai lần."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại tôi hết pin rồi, không quét mã được.","answer":"我的手机没电了，扫不了码。","answerPy":"Wǒ de shǒujī méi diàn le, sǎo bù liǎo mǎ.","explanation":"扫码 là từ ly hợp → 扫不了码."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài tập nhiều thế này, một ngày bạn làm xong được không?","answer":"这么多作业，你一天做得了吗？","answerPy":"Zhème duō zuòyè, nǐ yì tiān zuò de le ma?","explanation":"V得了吗？ hỏi khả năng hoàn thành."}]},{"point":"连词“再说” — vả lại, hơn nữa","items":[{"context":"“… vả lại hàng xóm với nhau phải giúp nhau.”","pre":"我提着这些东西就算锻炼身体了，","blank":"再说","post":"邻居之间就是要互相帮助啊。","options":["再说","不过","于是"],"answer":0,"explanation":"再说 bổ sung lý do thứ hai."},{"context":"“… vả lại ngoài trời vẫn đang mưa đấy.”","pre":"今天太晚了，别去超市了，再说外面还在下雨","blank":"呢","post":"。","options":["呢","吗","吧"],"answer":0,"explanation":"还在 + V + 呢: sự việc đang tiếp diễn (HSK 2/3)."},{"context":"“… vả lại đông người cũng vui hơn.”","pre":"你今天正好有时间，再说人多","blank":"也","post":"更热闹。","options":["也","就","才"],"answer":0,"explanation":"Vế 再说 hay có 也 / 还."},{"context":"“… coi như là tập thể dục rồi.” (ôn từ mới)","pre":"我提着这些东西就","blank":"算","post":"锻炼身体了。","options":["算","像","变"],"answer":0,"explanation":"就算……了 = coi như là."},{"context":"“… vả lại bạn đã có nhiều áo rồi.”","pre":"别买这件了，太贵了，","blank":"再说","post":"你已经有很多衣服了。","options":["再说","不过","甚至"],"answer":0,"explanation":"Hai lý do cùng chiều (đắt + đã có nhiều) → 再说."},{"type":"sort","context":"Sắp xếp: “Hôm nay muộn quá rồi, vả lại ngoài trời vẫn đang mưa.”","words":["今天","太晚了","，","再说","外面","还在下雨呢"],"answer":"今天太晚了，再说外面还在下雨呢。","explanation":"Lý do 1，再说 + lý do 2."},{"type":"sort","context":"Sắp xếp: “Căn nhà này gần trường, vả lại tiền thuê cũng không đắt.”","words":["这个房子","离学校很近","，","再说","房租","也不贵"],"answer":"这个房子离学校很近，再说房租也不贵。","explanation":"再说 + chủ ngữ + 也 + …"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"咱们打车去吧，时间不多了，再说东西也很多。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai lý do cùng chiều (ít thời gian + nhiều đồ) → đi taxi."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，再说太贵了，我不买了。","isCorrect":false,"correctVersion":"这件衣服很漂亮，不过太贵了，我不买了。","explanation":"Hai ý trái chiều → dùng 不过 (Bài 2 · điểm 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"再说外面很冷，你别出去了。","isCorrect":false,"correctVersion":"已经很晚了，再说外面很冷，你别出去了。","explanation":"再说 không mở đầu khi chưa có lý do thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng mình đi tàu điện ngầm đi, nhanh, vả lại cũng không đắt.","answer":"咱们坐地铁去吧，很快，再说也不贵。","answerPy":"Zánmen zuò dìtiě qù ba, hěn kuài, zàishuō yě bú guì.","explanation":"Lý do 1，再说 + 也 + lý do 2."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng khách sáo, việc này rất đơn giản, vả lại hàng xóm với nhau nên giúp đỡ lẫn nhau.","answer":"别客气，这件事很简单，再说邻居之间应该互相帮助。","answerPy":"Bié kèqi, zhè jiàn shì hěn jiǎndān, zàishuō línjū zhījiān yīnggāi hùxiāng bāngzhù.","explanation":"再说 + từ mới 之间, 互相."}]},{"point":"并列复句“既……，又/也……” — vừa … vừa …","items":[{"context":"“Cô ấy thấy như vậy vừa tiện, vừa …”","pre":"她觉得这样","blank":"既","post":"方便，又能锻炼身体。","options":["既","也","还"],"answer":0,"explanation":"Vế đầu dùng 既."},{"context":"“… vừa ngon vừa rẻ.”","pre":"这家饭馆的菜既好吃，","blank":"又","post":"便宜。","options":["又","再","就"],"answer":0,"explanation":"既……又……"},{"context":"“… cũng học được kiến thức lịch sử.”","pre":"我很喜欢这门课程，既能提高中文水平，","blank":"也","post":"能学到历史知识。","options":["也","都","才"],"answer":0,"explanation":"既……也…… (vế sau là cụm động từ)."},{"context":"“… lại còn bảo vệ được môi trường.”","pre":"她觉得骑车既方便，又能锻炼身体，","blank":"还","post":"能保护环境。","options":["还","既","就"],"answer":0,"explanation":"Ý thứ ba dùng 还."},{"context":"“… sạc điện cũng rất tiện.” (ôn từ mới)","pre":"电动车速度快，价格不高，","blank":"充电","post":"也很方便。","options":["充电","速度","力气"],"answer":0,"explanation":"充电 = sạc điện."},{"type":"sort","context":"Sắp xếp: “Món ăn ở nhà hàng này vừa ngon vừa rẻ.”","words":["这家","饭馆的菜","既","好吃","又","便宜"],"answer":"这家饭馆的菜既好吃又便宜。","explanation":"Chủ ngữ + 既 + A + 又 + B."},{"type":"sort","context":"Sắp xếp: “Đi xe đạp vừa rèn luyện thân thể, cũng bảo vệ được môi trường.”","words":["骑自行车","既","能锻炼身体","，","也","能保护环境"],"answer":"骑自行车既能锻炼身体，也能保护环境。","explanation":"既……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他既是我的老师，也是我的朋友。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 既是……也是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既他会说汉语，又他会说英语。","isCorrect":false,"correctVersion":"他既会说汉语，又会说英语。","explanation":"既 / 又 đứng sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服既漂亮，又不好看。","isCorrect":false,"correctVersion":"这件衣服既漂亮，又便宜。","explanation":"Hai ý mâu thuẫn — phải cùng chiều."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Xe điện vừa nhanh vừa rẻ, nên ngày càng thịnh hành.","answer":"电动车既快又便宜，所以越来越流行。","answerPy":"Diàndòngchē jì kuài yòu piányi, suǒyǐ yuèláiyuè liúxíng.","explanation":"既……又…… + 流行."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đi tàu điện ngầm vừa không bị tắc đường, vừa tiết kiệm được thời gian.","answer":"坐地铁既不堵车，又能省时间。","answerPy":"Zuò dìtiě jì bù dǔchē, yòu néng shěng shíjiān.","explanation":"既……又 / 也…… + 省."}]},{"point":"固定短语“来得及/来不及” — kịp / không kịp","items":[{"context":"“Người không kịp ăn sáng …”","pre":"没","blank":"来得及","post":"吃早饭的人在这里就能买到热包子。","options":["来得及","来不及","不来及"],"answer":0,"explanation":"没来得及 + V (✗ 没来不及)."},{"context":"“… tôi không kịp thông báo cho mọi người nữa.”","pre":"你现在才告诉我，我","blank":"来不及","post":"通知大家了。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"context":"“… 9 giờ xuất phát có kịp không?”","pre":"中午12点的飞机，咱们9点出发","blank":"来得及","post":"吗？","options":["来得及","来不及了","没来得及"],"answer":0,"explanation":"Hỏi: ……来得及吗？"},{"context":"“… kịp ăn sáng.”","pre":"别着急，还有15分钟，咱们来得及吃","blank":"早饭","post":"。","options":["早饭","速度","乘客"],"answer":0,"explanation":"来得及 + V + O."},{"context":"“… bạn không kịp đi tàu điện ngầm về nữa …”","pre":"时间太晚了，你","blank":"来不及","post":"坐地铁回去了，就住在我们这儿吧。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"type":"sort","context":"Sắp xếp: “Còn nửa tiếng, chúng mình kịp ăn sáng.”","words":["还有","半个小时","，","咱们","来得及","吃早饭"],"answer":"还有半个小时，咱们来得及吃早饭。","explanation":"来得及 + V."},{"type":"sort","context":"Sắp xếp: “Sáng nay tôi chưa kịp ăn sáng đã đi làm rồi.”","words":["我","早上","没来得及","吃早饭","就","去上班了"],"answer":"我早上没来得及吃早饭就去上班了。","explanation":"没来得及 + V + 就……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在出发还来得及。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 还来得及 = vẫn còn kịp."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天我没来不及跟你说再见。","isCorrect":false,"correctVersion":"昨天我没来得及跟你说再见。","explanation":"Việc đã qua: 没来得及."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"飞机十点起飞，现在已经九点半了，来得及不了。","isCorrect":false,"correctVersion":"飞机十点起飞，现在已经九点半了，来不及了。","explanation":"Phủ định là 来不及, không có 来得及不了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Sáng nay tôi dậy muộn, không kịp ăn sáng.","answer":"今天早上我起晚了，没来得及吃早饭。","answerPy":"Jīntiān zǎoshang wǒ qǐ wǎn le, méi láidejí chī zǎofàn.","explanation":"Việc đã qua → 没来得及 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Phim 8 giờ bắt đầu, bây giờ đi còn kịp không?","answer":"电影八点开始，现在去还来得及吗？","answerPy":"Diànyǐng bā diǎn kāishǐ, xiànzài qù hái láidejí ma?","explanation":"……，来得及吗？"}]}],"/lessons/hsk4v3-bai-5.html":[{"point":"范围副词“至少” — ít nhất, tối thiểu","items":[{"context":"“Cháu sang Trung Quốc ít nhất hai tháng rồi …”","pre":"家月，你来中国","blank":"至少","post":"两个月了，习惯吃中餐了吗？","options":["至少","专门","任何"],"answer":0,"explanation":"至少 + cụm thời gian."},{"context":"“Mỗi năm có ít nhất hai trăm du học sinh …”","pre":"每年至少","blank":"有","post":"两百名留学生来我校学习中文专业。","options":["有","是","在"],"answer":0,"explanation":"至少 + 有 + số lượng."},{"context":"“Tuy chưa gặp mặt, nhưng ít ra cũng đã trò chuyện trên mạng nhiều lần.”","pre":"我们虽然没有见过面，","blank":"但","post":"至少在网上聊过很多次。","options":["但","就","于是"],"answer":0,"explanation":"虽然……，但至少…… — ôn 虽然……但是…… (HSK 3)."},{"context":"“Đi xe đạp điện ít nhất cũng nhanh được mười phút.”","pre":"骑电动车至少","blank":"能","post":"快十分钟。","options":["能","敢","够"],"answer":0,"explanation":"至少 + 能 + V + số lượng."},{"context":"“Cũ thì cũ, nhưng ít ra cũng sạch.” (ôn Bài 3)","pre":"这个房子旧是旧，","blank":"不过","post":"至少很干净。","options":["不过","因为","要是"],"answer":0,"explanation":"×是×，不过至少…… — ôn Bài 3 · điểm 1."},{"type":"sort","context":"Sắp xếp: “Mỗi ngày tôi học ít nhất hai tiếng.”","words":["我","每天","至少","学习","两个小时"],"answer":"我每天至少学习两个小时。","explanation":"Chủ ngữ + thời gian + 至少 + V + thời lượng."},{"type":"sort","context":"Sắp xếp: “Năm nhất cao học phải chọn ít nhất ba môn.”","words":["研究生一年级","至少","要","选","三门课"],"answer":"研究生一年级至少要选三门课。","explanation":"至少 + 要 + V + số lượng."},{"type":"sort","context":"Sắp xếp: “Căn nhà này cũ thì cũ, nhưng ít ra cũng sạch.”","words":["这个","房子","旧是旧","，","不过","至少","很干净"],"answer":"这个房子旧是旧，不过至少很干净。","explanation":"Ôn ×是×，不过…… + 至少."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我每天睡觉八个小时至少。","isCorrect":false,"correctVersion":"我每天至少睡八个小时。","explanation":"至少 không đứng cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"每年至少有两百名留学生来我校学习。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 至少 + 有 + số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他至少的朋友有十个。","isCorrect":false,"correctVersion":"他至少有十个朋友。","explanation":"至少 là phó từ, không thêm 的 làm định ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Muốn học giỏi tiếng Trung, mỗi ngày ít nhất phải học một tiếng.","answer":"要想学好中文，每天至少要学习一个小时。","answerPy":"Yào xiǎng xué hǎo Zhōngwén, měi tiān zhìshǎo yào xuéxí yí gè xiǎoshí.","explanation":"至少 + 要 + V + thời lượng."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã đến Bắc Kinh ít nhất năm lần rồi.","answer":"我至少来过北京五次了。","answerPy":"Wǒ zhìshǎo lái guò Běijīng wǔ cì le.","explanation":"至少 + V过 + số lần."}]},{"point":"副词/动词“够” — thật là …; đủ","items":[{"context":"“Trình độ tiếng Trung của cậu cao thật đấy!”","pre":"你的中文水平","blank":"够","post":"高的，这都听懂了！","options":["够","不够","至少"],"answer":0,"explanation":"够 + Adj + 的 = thật là …"},{"context":"“Vẫn chưa đủ ngọt, thêm chút đường đi.”","pre":"我尝了一下，还","blank":"不够","post":"甜，再加一点儿糖吧。","options":["不够","够","至少"],"answer":0,"explanation":"不够 + Adj = chưa đủ …"},{"context":"“Bốn món có đủ không?”","pre":"明天请家月和李文来家里吃饭，四个菜","blank":"够不够","post":"？","options":["够不够","够没够","不够够"],"answer":0,"explanation":"Câu hỏi chính phản: 够不够."},{"context":"“Hôm nay trời lạnh thật đấy, mặc thêm áo vào.”","pre":"今天的天气够冷","blank":"的","post":"，多穿点儿衣服吧。","options":["的","了","吗"],"answer":0,"explanation":"Khung cố định 够……的."},{"context":"“… thời gian không đủ.”","pre":"完成这个工作需要三天，现在只有两天，时间","blank":"不够","post":"。","options":["不够","够的","至少"],"answer":0,"explanation":"N + 不够 (động từ)."},{"type":"sort","context":"Sắp xếp: “Nhà bạn to thật đấy.”","words":["你家","房子","够","大","的"],"answer":"你家房子够大的。","explanation":"够 + Adj + 的."},{"type":"sort","context":"Sắp xếp: “Cái thùng này không đủ to, không để vừa nhiều đồ thế.”","words":["这个","箱子","不够大","，","放不下","这么多东西"],"answer":"这个箱子不够大，放不下这么多东西。","explanation":"不够 + Adj + bổ ngữ khả năng 放不下."},{"type":"sort","context":"Sắp xếp: “Tôi nếm thử rồi, vẫn chưa đủ ngọt.”","words":["我","尝了一下","，","还","不够","甜"],"answer":"我尝了一下，还不够甜。","explanation":"还 + 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个箱子够不大，放不下这么多东西。","isCorrect":false,"correctVersion":"这个箱子不够大，放不下这么多东西。","explanation":"Phủ định: 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你的中文水平够高的，这都听懂了！","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够……的 cảm thán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们只有两个人，三个菜够了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够 làm động từ — đủ (số lượng)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này vẫn chưa đủ cay, cho thêm chút ớt nữa đi.","answer":"这道菜还不够辣，再放一点儿辣椒吧。","answerPy":"Zhè dào cài hái búgòu là, zài fàng yìdiǎnr làjiāo ba.","explanation":"不够 + Adj; từ mới 辣椒."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm nay trời nóng thật đấy!","answer":"今天天气够热的！","answerPy":"Jīntiān tiānqì gòu rè de!","explanation":"够 + Adj + 的."}]},{"point":"固定格式“各×各的” — ai … nấy, mỗi người tự …","items":[{"context":"“… vẫn là ai trả phần nấy thì hợp hơn.”","pre":"大家觉得还是各付","blank":"各","post":"的更合适。","options":["各","自己","每"],"answer":0,"explanation":"各 + V + 各 + 的."},{"context":"“… ai bận việc nấy.”","pre":"到了办公室，大家就开始各","blank":"忙","post":"各的了。","options":["忙","付","坐"],"answer":0,"explanation":"各忙各的."},{"context":"“… ai đọc sách nấy.”","pre":"在图书馆里，大家都很安静，各看各的","blank":"书","post":"。","options":["书","饭","菜"],"answer":0,"explanation":"各V各的 + danh từ."},{"context":"“Khẩu vị họ khác nhau, thế là mỗi người ăn phần mình.” (ôn Bài 3)","pre":"他们口味不同，","blank":"于是","post":"就各吃各的。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 nối kết quả — Bài 3 · điểm 4."},{"context":"“… mỗi người mua một kiểu.”","pre":"他们想买的东西不一样，到了商场以后就各买","blank":"各的","post":"了。","options":["各的","自己","他的"],"answer":0,"explanation":"各买各的."},{"type":"sort","context":"Sắp xếp: “Mọi người thấy vẫn là ai trả phần nấy thì hợp hơn.”","words":["大家","觉得","还是","各付各的","更合适"],"answer":"大家觉得还是各付各的更合适。","explanation":"还是……更合适 + 各付各的."},{"type":"sort","context":"Sắp xếp: “Đến văn phòng, mọi người bắt đầu ai bận việc nấy.”","words":["到了","办公室","，","大家","就","开始","各忙各的了"],"answer":"到了办公室，大家就开始各忙各的了。","explanation":"Chủ ngữ số nhiều + 就 + 各V各的."},{"type":"sort","context":"Sắp xếp: “Thầy nói xong, mọi người ai làm bài nấy.”","words":["老师","说完","以后","，","大家","就","各做各的"],"answer":"老师说完以后，大家就各做各的。","explanation":"……以后，大家就各V各的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我各吃各的。","isCorrect":false,"correctVersion":"我们各吃各的。","explanation":"Chủ ngữ phải là nhiều người."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在图书馆里，大家都很安静，各看各的书。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 各看各的 + 书."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他们各的做各的。","isCorrect":false,"correctVersion":"他们各做各的。","explanation":"Không có 的 sau 各 thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn bè đi ăn với nhau, chúng tôi thường ai trả phần nấy.","answer":"朋友一起吃饭，我们一般各付各的。","answerPy":"Péngyou yìqǐ chīfàn, wǒmen yìbān gè fù gè de.","explanation":"各付各的 + từ mới 聚餐."}]},{"point":"介词“等” — đợi đến khi, chờ đến lúc","items":[{"context":"“… người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","pre":"如果聚餐时有老人，年轻人要","blank":"等","post":"老人坐下后再坐。","options":["等","在","从"],"answer":0,"explanation":"等 + sự việc + 后，再 + V."},{"context":"“Đợi tớ làm xong bài rồi mới đi chơi với cậu.”","pre":"等我写完作业，","blank":"再","post":"跟你出去玩。","options":["再","又","还"],"answer":0,"explanation":"等……，再…… (việc chưa xảy ra)."},{"context":"“… tàu đã chạy mất rồi.”","pre":"等我们到火车站的时候，火车","blank":"已经","post":"开走了。","options":["已经","正在","马上"],"answer":0,"explanation":"等……的时候，已经……了."},{"context":"“Đừng vội, đợi tớ xong việc thì sẽ đi tìm cậu.”","pre":"别着急，等我忙完了","blank":"就","post":"去找你。","options":["就","才","也"],"answer":0,"explanation":"等……，就…… (đáp án gợi ý của sách)."},{"context":"“Đến lúc chúng tôi chạy tới thì đã không kịp rồi.” (ôn Bài 4)","pre":"","blank":"等","post":"我们赶到的时候，已经来不及了。","options":["等","随着","要是"],"answer":0,"explanation":"等……的时候 + 来不及 (Bài 4 · điểm 4)."},{"type":"sort","context":"Sắp xếp: “Đợi tớ làm xong bài tập rồi đi chơi với cậu.”","words":["等","我","写完作业","，","再","跟你","出去玩"],"answer":"等我写完作业，再跟你出去玩。","explanation":"等……，再……"},{"type":"sort","context":"Sắp xếp: “Người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","words":["年轻人","要","等","老人","坐下后","再坐"],"answer":"年轻人要等老人坐下后再坐。","explanation":"Chủ ngữ + 要 + 等 + sự việc + 后 + 再 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我写完作业等，再跟你出去玩。","isCorrect":false,"correctVersion":"等我写完作业，再跟你出去玩。","explanation":"等 đứng đầu vế câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等我们到火车站的时候，火车已经开走了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 等……的时候，已经……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等你办了信用卡以后，你又能先花钱再还钱了。","isCorrect":false,"correctVersion":"等你办了信用卡以后，你就能先花钱再还钱了。","explanation":"Kết quả khi điều kiện đạt được dùng 就, không dùng 又."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi mọi người đến đủ rồi chúng ta mới bắt đầu ăn.","answer":"等大家都到了，我们再开始吃。","answerPy":"Děng dàjiā dōu dào le, wǒmen zài kāishǐ chī.","explanation":"等……，再……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi tôi tốt nghiệp xong, tôi sẽ về nước làm giáo viên.","answer":"等我毕业以后，就回国当老师。","answerPy":"Děng wǒ bìyè yǐhòu, jiù huíguó dāng lǎoshī.","explanation":"等……，就…… + 当 (Bài 1)."}]}],"/lessons/hsk4v3-bai-6.html":[{"point":"形容词“厉害” — … dữ dội, … kinh khủng","items":[{"context":"“… ho dữ lắm.”","pre":"我还发烧，一直咳嗽，咳得很","blank":"厉害","post":"。","options":["厉害","有效","按时"],"answer":0,"explanation":"V + 得 + 很 + 厉害."},{"context":"“… hôm nay chân đau dữ dội.”","pre":"我昨天跑步跑多了，今天腿疼","blank":"得","post":"厉害。","options":["得","的","地"],"answer":0,"explanation":"Bổ ngữ mức độ nối bằng 得."},{"context":"“Món này cay kinh khủng …”","pre":"这道菜辣得","blank":"厉害","post":"，我吃了一口就不敢再吃了。","options":["厉害","好吃","一点儿"],"answer":0,"explanation":"Adj + 得 + 厉害."},{"context":"“Gió thổi mạnh lắm, đợi lát nữa hãy đi.”","pre":"外面风刮","blank":"得","post":"很厉害，咱们等会儿再走吧。","options":["得","了","着"],"answer":0,"explanation":"刮 + 得 + 很厉害."},{"context":"“… mau đi bệnh viện khám đi.” (ôn từ mới)","pre":"我看你病得很厉害，","blank":"赶快","post":"去医院看看吧。","options":["赶快","偶尔","按时"],"answer":0,"explanation":"赶快 + V: giục làm ngay."},{"type":"sort","context":"Sắp xếp: “Bụng tôi đau dữ dội.”","words":["我","肚子","疼","得","很厉害"],"answer":"我肚子疼得很厉害。","explanation":"Adj + 得 + 很厉害."},{"type":"sort","context":"Sắp xếp: “Anh ấy ho rất dữ.”","words":["他","咳嗽","咳","得","特别厉害"],"answer":"他咳嗽咳得特别厉害。","explanation":"Động từ có tân ngữ → lặp động từ."},{"type":"sort","context":"Sắp xếp: “Hôm nay lạnh kinh khủng, mặc thêm áo vào.”","words":["今天","冷","得","厉害","，","多穿点儿衣服"],"answer":"今天冷得厉害，多穿点儿衣服。","explanation":"Adj + 得 + 厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这道菜辣得很厉害，我不敢吃。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj + 得 + 很厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我很疼得厉害。","isCorrect":false,"correctVersion":"我疼得很厉害。","explanation":"很 đứng trước 厉害, không đứng trước 疼."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他咳嗽得厉害很。","isCorrect":false,"correctVersion":"他咳嗽得很厉害。","explanation":"Phó từ 很 đứng trước 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm qua tôi ngủ muộn quá, hôm nay đầu đau dữ dội.","answer":"昨天我睡得太晚了，今天头疼得厉害。","answerPy":"Zuótiān wǒ shuì de tài wǎn le, jīntiān tóu téng de lìhai.","explanation":"头 + 疼 + 得 + (很) + 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này cay kinh khủng, có điều tôi vẫn ăn được.","answer":"这道菜辣得厉害，不过我吃得了。","answerPy":"Zhè dào cài là de lìhai, búguò wǒ chī de liǎo.","explanation":"辣得厉害 + ôn 不过 (Bài 2) và V得了 (Bài 4)."}]},{"point":"固定格式“（没）有什么（好）×的” — có gì mà phải …, chẳng có gì (đáng) …","items":[{"context":"“Cậu với tớ có gì mà phải khách sáo.”","pre":"你跟我有什么好","blank":"客气","post":"的。","options":["客气","厉害","严重"],"answer":0,"explanation":"有什么好 + V + 的."},{"context":"“… chẳng có gì lạ cả.”","pre":"这种事在网上有很多，没有什么奇怪","blank":"的","post":"。","options":["的","了","吗"],"answer":0,"explanation":"Cuối câu bắt buộc có 的."},{"context":"“… chẳng có gì đáng mua.”","pre":"这家商场里的东西都很一般，没有什么","blank":"好","post":"买的。","options":["好","很","太"],"answer":0,"explanation":"好 + V = đáng để làm."},{"context":"“Tớ chỉ bị cảm nhẹ, chẳng có gì phải lo.”","pre":"我得的只是小感冒，没有什么好","blank":"担心","post":"的。","options":["担心","放心","高兴"],"answer":0,"explanation":"没有什么好担心的."},{"context":"“… chẳng có gì phải dọn.”","pre":"前天刚打扫过，还很干净，","blank":"没有","post":"什么好打扫的。","options":["没有","不是","不"],"answer":0,"explanation":"Phủ định dùng 没有什么, không dùng 不什么."},{"type":"sort","context":"Sắp xếp: “Chúng mình là bạn thân, chẳng có gì phải khách sáo.”","words":["咱们","是","好朋友","，","没有什么","好","客气","的"],"answer":"咱们是好朋友，没有什么好客气的。","explanation":"没有什么 + 好 + V + 的."},{"type":"sort","context":"Sắp xếp: “Vấn đề này đơn giản lắm, có gì mà phải bàn.”","words":["这个问题","很简单","，","有什么","好","讨论","的"],"answer":"这个问题很简单，有什么好讨论的？","explanation":"有什么好 + V + 的: hỏi tu từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你跟我有什么好客气的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: câu hỏi tu từ, gạt đi lời cảm ơn."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这部电影很一般，没有什么好看。","isCorrect":false,"correctVersion":"这部电影很一般，没有什么好看的。","explanation":"Thiếu 的 cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"考试很简单，没有什么好紧张的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 没有什么好 + V + 的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng ta là bạn bè, có gì mà phải khách sáo.","answer":"我们是朋友，有什么好客气的。","answerPy":"Wǒmen shì péngyou, yǒu shénme hǎo kèqi de.","explanation":"有什么好客气的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bộ phim này rất bình thường, chẳng có gì đáng xem.","answer":"这部电影很一般，没有什么好看的。","answerPy":"Zhè bù diànyǐng hěn yìbān, méiyǒu shénme hǎokàn de.","explanation":"没有什么好看的."}]},{"point":"频率副词“偶尔” — thỉnh thoảng, lâu lâu mới","items":[{"context":"“… lâu lâu mới ốm một lần.”","pre":"她平时身体不错，","blank":"偶尔","post":"才会生一次病。","options":["偶尔","经常","总是"],"answer":0,"explanation":"偶尔 + 才: hiếm khi."},{"context":"“… thỉnh thoảng mới ra rạp.”","pre":"他经常在家看电影，偶尔","blank":"才","post":"去电影院看。","options":["才","就","都"],"answer":0,"explanation":"偶尔才 + V."},{"context":"“… thỉnh thoảng đi ăn ngoài với bạn.”","pre":"我一般都在学校食堂吃饭，","blank":"偶尔","post":"会跟朋友一起出去吃。","options":["偶尔","一直","按时"],"answer":0,"explanation":"一般……，偶尔……"},{"context":"“… có điều thỉnh thoảng cũng muốn ăn đồ ngọt.”","pre":"我喜欢吃辣的菜，不过偶尔","blank":"也","post":"想吃点儿甜的。","options":["也","才","就"],"answer":0,"explanation":"偶尔也 = cũng có lúc."},{"context":"“… uống thuốc đúng giờ.” (phân biệt với 偶尔)","pre":"医生让她回家以后","blank":"按时","post":"吃药，多喝水，多休息。","options":["按时","偶尔","光"],"answer":0,"explanation":"Uống thuốc phải 按时, không thể 偶尔."},{"type":"sort","context":"Sắp xếp: “Tôi thường đi tàu điện ngầm, thỉnh thoảng mới đi taxi.”","words":["我","一般","坐地铁","，","偶尔","才","打车"],"answer":"我一般坐地铁，偶尔才打车。","explanation":"一般……，偶尔才……"},{"type":"sort","context":"Sắp xếp: “Bình thường anh ấy không uống rượu, thỉnh thoảng uống một chút.”","words":["他","平时","不喝酒","，","偶尔","会","喝一点儿"],"answer":"他平时不喝酒，偶尔会喝一点儿。","explanation":"偶尔会 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我吃偶尔辣的菜。","isCorrect":false,"correctVersion":"我偶尔吃辣的菜。","explanation":"偶尔 đứng trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她身体很好，偶尔才生一次病。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 偶尔才 + 生一次病."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天都偶尔去跑步。","isCorrect":false,"correctVersion":"他偶尔去跑步。","explanation":"每天都 (ngày nào cũng) mâu thuẫn với 偶尔."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi thường học ở thư viện, thỉnh thoảng mới học ở ký túc xá.","answer":"我经常在图书馆学习，偶尔才在宿舍学习。","answerPy":"Wǒ jīngcháng zài túshūguǎn xuéxí, ǒu'ěr cái zài sù shè xuéxí.","explanation":"经常 / 一般……，偶尔才……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy rất ít khi ốm, thỉnh thoảng mới bị cảm một lần.","answer":"他很少生病，偶尔才感冒一次。","answerPy":"Tā hěn shǎo shēngbìng, ǒu'ěr cái gǎnmào yí cì.","explanation":"偶尔才 + V + 一次."}]},{"point":"目的复句“……，好……” — …, để (tiện / dễ) …","items":[{"context":"“… để đưa ra cách điều trị phù hợp.”","pre":"医生有时还会做一些检查，","blank":"好","post":"给出合适的治疗方法。","options":["好","就","才"],"answer":0,"explanation":"……，好 + V (mục đích)."},{"context":"“Các bạn tìm hiểu tình hình trước …”","pre":"你们先了解一下","blank":"情况","post":"，好做出决定。","options":["情况","过程","结果"],"answer":0,"explanation":"了解 + 情况."},{"context":"“… sau này có việc gì thì tiện liên lạc với tôi.”","pre":"我把电话号码告诉你，以后有什么事","blank":"好","post":"联系我。","options":["好","再","又"],"answer":0,"explanation":"好 đứng ngay trước động từ 联系."},{"context":"“… để họ yên tâm.”","pre":"我每天都给家人打电话，好","blank":"让","post":"他们放心。","options":["让","被","把"],"answer":0,"explanation":"好 + 让 + ai + Adj."},{"context":"“Khám bệnh ở Trung Quốc phải lấy số trước …” (ôn từ mới)","pre":"在中国看病要先","blank":"挂号","post":"，然后再去找医生。","options":["挂号","打针","收费"],"answer":0,"explanation":"先挂号，然后再看病."},{"type":"sort","context":"Sắp xếp: “Bạn ngủ sớm đi, để mai còn dậy sớm.”","words":["你","早点儿","睡","，","明天","好","早起"],"answer":"你早点儿睡，明天好早起。","explanation":"Trạng ngữ 明天 + 好 + V."},{"type":"sort","context":"Sắp xếp: “Xin để lại địa chỉ, để chúng tôi tiện gửi đồ cho bạn.”","words":["请","留下","你的地址","，","我们","好","给你寄东西"],"answer":"请留下你的地址，我们好给你寄东西。","explanation":"Chủ ngữ 我们 + 好 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把电话号码告诉你，以后有什么事好联系我。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 好 đứng trước 联系."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"好让他们放心，我每天给家人打电话。","isCorrect":false,"correctVersion":"我每天给家人打电话，好让他们放心。","explanation":"Vế 好 (mục đích) đặt sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你先在大厅休息，我去排队挂号，好节省时间。","isCorrect":true,"correctVersion":"","explanation":"Đúng: vế cuối 好 + V nêu mục đích."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn mang theo hộ chiếu, để tiện đi lấy số.","answer":"你带上护照，好去挂号。","answerPy":"Nǐ dài shàng hùzhào, hǎo qù guàhào.","explanation":"……，好 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi ghi lại các bước nấu món ăn, để lần sau dễ làm.","answer":"我把做菜的过程写下来，下次好做。","answerPy":"Wǒ bǎ zuò cài de guòchéng xiě xiàlái, xià cì hǎo zuò.","explanation":"Trạng ngữ 下次 + 好 + V."}]}]});
